    "intervention": "Phân loại và xử trí 4 thể SSTI (có mủ, không mủ, tái phát, thể loét chi dưới); Áp dụng thời gian điều trị chuẩn 5 ngày cho SSTI không biến chứng (Hepburn RCT); Thay thế Clindamycin bằng Linezolid phối hợp Piperacillin-Tazobactam cho nhiễm trùng hoại tử mô mềm (NSTI) do liên cầu kháng Clindamycin gia tăng; Loại bỏ hoàn toàn Ertapenem; Cảnh báo hồng ban hai bên đối xứng cực hiếm khi là viêm mô tế bào (nghĩ đến viêm da ứ máu); Đổi TMP-SMX sang Linezolid/Doxycycline ở BN tăng kali hoặc creatinine máu nền; Phác đồ khử khuẩn Mupirocin + Chlorhexidine 5 ngày/tháng x 3 tháng cho cả gia đình khi áp xe tái phát; Phẫu thuật cắt lọc sạch xương viêm trong loét bàn chân chỉ cần 3 ngày kháng sinh.",
    "primaryEndpoint": "Chuẩn hóa phác đồ điều trị, rút ngắn thời gian dùng kháng sinh còn 5 ngày, đối phó hiệu quả với xu hướng kháng Clindamycin của liên cầu và ngăn chặn tái phát bền vững.",
    "keyResults": "Kháng sinh 5 ngày tương đương 10 ngày trong SSTI không biến chứng | Linezolid + Pip-Tazo tối ưu hóa điều trị NSTI thay cho Clindamycin | Tránh lạm dụng kháng sinh cho hồng ban 2 bên chân | Khử khuẩn cả hộ gia đình triệt tiêu nguồn lây chéo tụ cầu | Cắt sạch xương viêm giúp rút ngắn kháng sinh chỉ còn 3 ngày.",
    "summary": "Hướng dẫn thực hành lâm sàng toàn diện cập nhật tháng 1/2026 của UCSF Health về quản lý nhiễm trùng da và mô mềm ở người lớn: Tích hợp 4 lưu đồ thuật toán trực quan hóa chuẩn Editorial, chuẩn hóa thời gian điều trị 5 ngày, cập nhật đề kháng Clindamycin chuyển sang Linezolid cho NSTI, bảo vệ thận tránh tăng kali máu của TMP-SMX và quy trình khử khuẩn chu kỳ 3 tháng cho cả gia đình.",
    "detailedConclusion": "Bác sĩ lâm sàng áp dụng phác đồ 5 ngày cho SSTI không biến chứng. Khi nghi ngờ hoại tử (NSTI), dùng ngay Linezolid + Piperacillin-Tazobactam và phẫu thuật khẩn. Kiểm tra hồng ban hai bên để tránh chẩn đoán nhầm viêm da ứ máu. Kiểm tra kali/creatinine trước khi kê TMP-SMX.",
    "drug": "Cefazolin, Cephalexin, Vancomycin, Linezolid, Trimethoprim/sulfamethoxazole (TMP/SMX), Clindamycin, Doxycycline, Ceftriaxone, Piperacillin/tazobactam, Mupirocin",
    "population": "Bệnh nhân trưởng thành (ngoại trú hoặc nội trú) nghi ngờ hoặc xác định mắc nhiễm trùng da và mô mềm (SSTI), bao gồm viêm mô tế bào (không mủ), áp-xe (có mủ), nhiễm trùng hoại tử và loét chân nhiễm trùng.",
