    "intervention": "Hướng dẫn thực hành lâm sàng tiêu chuẩn của Hiệp hội Nội tiết Lâm sàng Hoa Kỳ (AACE 2025) về quản lý dược lý rối loạn lipid máu ở người trưởng thành: Đánh giá nguy cơ ASCVD bằng công cụ đã kiểm định (PCE, FRS, PREVENT); Nhận diện giá trị gia tăng hạn chế (incremental) của các yếu tố tăng cường nguy cơ (CAC chỉ tăng c-statistic -0.01 đến 0.088, ApoB chỉ tăng 0.0004 đến 0.002, Lp(a) chỉ tăng 0 đến 0.0164; chống chỉ định đo lặp lại CAC); Khuyến cáo bổ sung Kháng thể đơn dòng ức chế PCSK9 (Evolocumab 140mg/2 tuần hoặc 420mg/tháng, Alirocumab 75-150mg/2 tuần hoặc 300mg/tháng) vào statin liều tối đa khi có ASCVD hoặc nguy cơ cao chưa đạt LDL-C < 70 mg/dL (giảm 11-18 ca MI/1000 người theo FOURIER và ODYSSEY OUTCOMES); Chống lại dùng kháng thể PCSK9 ở người không có ASCVD; Nhận định Inclisiran (siRNA GalNAc hướng gan qua ASGPR, xúc tác cắt mRNA PCSK9 qua RISC, liều 0-3-6 tháng) chưa đủ bằng chứng cải thiện biến cố ASCVD cứng; Khuyến cáo bổ sung Axit Bempedoic (180 mg/ngày) cho bệnh nhân không dung nạp statin có ASCVD hoặc nguy cơ cao (cơ chế tiền chất hoạt hóa bởi ACSVL1 gan ức chế ATP-citrate lyase mà không gây đau cơ, thử nghiệm CLEAR Outcomes giảm 11 ca MI/1000 người, cảnh báo gút, sỏi mật, đứt gân); Quản lý tăng triglycerid máu 150-499 mg/dL: Gợi ý phối hợp Icosapent Ethyl (EPA 4g/ngày, REDUCE-IT giảm 8 ca MI/1000 người, cảnh báo rung nhĩ và xuất huyết lớn), Chống lại phối hợp EPA + DHA (STRENGTH không giảm biến cố, tăng tác dụng phụ, DHA làm tăng LDL-C), và Khuyến cáo mạnh CHỐNG LẠI phối hợp Niacin (AIM-HIGH và HPS2-THRIVE thất bại, tăng 98 ca ngừng thuốc/1000 người vì tác dụng phụ nghiêm trọng, FDA thu hồi); Tái thiết lập đích LDL-C < 70 mg/dL (1.8 mmol/L) thay vì < 55 mg/dL do thiếu bằng chứng giảm tử vong bổ sung và giảm gánh nặng đa dược trị.",
    "primaryEndpoint": "Cung cấp các khuyến cáo dựa trên bằng chứng GRADE về sử dụng thuốc hạ lipid máu không phải statin (non-statin) nhằm giảm biến cố tim mạch do xơ vữa (ASCVD), tối ưu hóa đích LDL-C < 70 mg/dL, chuẩn hóa quản lý tăng triglycerid máu và phòng ngừa tác dụng phụ đa dược trị.",
    "keyResults": "Kháng thể PCSK9 (Evolocumab, Alirocumab) giảm 11-18 ca MI/1000 người ở nhóm có ASCVD hoặc nguy cơ cao chưa đạt đích | Axit Bempedoic là lựa chọn thay thế an toàn không gây đau cơ cho người không dung nạp statin | Inclisiran chưa đủ bằng chứng cải thiện biến cố tim mạch cứng | Icosapent Ethyl (EPA đơn trị 4g/ngày) giảm 8 ca MI/1000 người ở nhóm TG 150-499 mg/dL kèm ASCVD | Chống lại EPA + DHA vì không giảm biến cố tim mạch | Khuyến cáo mạnh CHỐNG LẠI Niacin do tác hại vượt trội lợi ích và FDA đã rút cấp phép | Tái xác lập đích điều trị LDL-C < 70 mg/dL thực tế, bãi bỏ đích ép < 55 mg/dL.",
    "summary": "Hướng dẫn thực hành lâm sàng tiêu chuẩn của Hiệp hội Nội tiết Lâm sàng Hoa Kỳ (AACE 2025) về quản lý dược lý rối loạn lipid máu ở người trưởng thành: Quy định vai trò các thuốc non-statin (Kháng thể PCSK9, Axit Bempedoic, Inclisiran), chỉ định EPA đơn trị thay vì phối hợp EPA+DHA, cấm chỉ định Niacin, và tái thiết lập mục tiêu điều trị LDL-C < 70 mg/dL.",
    "detailedConclusion": "Bác sĩ lâm sàng tiếp cận bệnh nhân rối loạn lipid máu: Đánh giá nguy cơ ASCVD và khởi trị Statin liều dung nạp tối đa. Nếu đã có ASCVD hoặc nguy cơ cao mà LDL-C vẫn ≥ 70 mg/dL: Gợi ý phối hợp thêm Kháng thể đơn dòng PCSK9 (Evolocumab hoặc Alirocumab). Nếu không dung nạp Statin do đau cơ: Chỉ định Axit Bempedoic (180 mg/ngày) theo dõi acid uric và gân gót. Nếu Triglycerid 150–499 mg/dL kèm ASCVD: Bổ sung Icosapent Ethyl (EPA 4g/ngày) và theo dõi nguy cơ rung nhĩ; TUYỆT ĐỐI KHÔNG dùng EPA + DHA hoặc Niacin. Đích LDL-C khuyến cáo là < 70 mg/dL (1.8 mmol/L).",
    "drug": "Evolocumab, Alirocumab, Inclisiran, Bempedoic acid, Eicosapentaenoic acid (EPA), Icosapent ethyl (IPE), Docosahexaenoic acid (DHA), Niacin, Statins, Ezetimibe",
    "population": "Người trưởng thành mắc bệnh rối loạn lipid máu có bệnh lý tim mạch do xơ vữa (ASCVD) hoặc có nguy cơ cao tiến triển các biến cố tim mạch.",
