    "intervention": "Sử dụng các hệ thống thang điểm phân tầng nguy cơ tử vong CRB65 (cho chăm sóc ban đầu) và CURB65 (cho bệnh viện) phối hợp đánh giá lâm sàng; chỉ định xét nghiệm biomarker (CRP, PCT) động học sau 3-4 ngày điều trị; rút ngắn thời gian dùng kháng sinh dựa trên bằng chứng và xem xét liệu pháp Corticosteroid bổ trợ (Hydrocortisone truyền tĩnh mạch) ở bệnh nhân viêm phổi cộng đồng (CAP) mức độ nặng.",
    "primaryEndpoint": "Tối ưu hóa quy trình chẩn đoán sớm và quản lý viêm phổi mắc phải tại cộng đồng (CAP) và viêm phổi mắc phải tại bệnh viện (HAP) ở trẻ em và người trưởng thành, cải thiện tỷ lệ sống còn và thúc đẩy chương trình quản lý sử dụng kháng sinh (antimicrobial stewardship).",
    "keyResults": "COL: Tử vong CAP nhập viện: 15.0% | Tử vong CAP tại ICU: 30.0%",
    "impact": "practice-changing",
    "year": 2025,
    "organization": "NICE",
    "population": "Trẻ em, người trưởng thành và phụ nữ có thai bị nghi ngờ hoặc đã xác định mắc bệnh viêm phổi mắc phải tại cộng đồng (CAP) hoặc viêm phổi mắc phải tại bệnh viện (HAP).",
    "summary": "Hướng dẫn lâm sàng NG250 cập nhật năm 2025 của NICE thay thế các hướng dẫn cũ (NG138, NG139, CG191) nhằm chuẩn hóa toàn diện quy trình xử trí viêm phổi ở cả người lớn và trẻ em. Tài liệu nhấn mạnh việc phân tầng mức độ nặng bằng thang điểm CRB65/CURB65, rút ngắn thời gian điều trị kháng sinh xuống 5 ngày cho người lớn và chỉ 3 ngày cho trẻ em ≥ 3 tháng mắc CAP thể nhẹ không biến chứng, đồng thời khuyến cáo sử dụng Corticosteroid phối hợp cho CAP mức độ nặng.",
    "detailedConclusion": "Đối với CAP ở người lớn, bắt buộc thực hiện chẩn đoán và chụp X-quang phổi trong vòng 4 giờ kể từ khi nhập viện và bắt đầu kháng sinh ngay lập tức. Thang điểm CRB65 và CURB65 được khuyến cáo sử dụng để hỗ trợ ra quyết định chung về địa điểm điều trị (cho phép điều trị tại nhà qua mô hình bệnh viện tại nhà hoặc khoa bệnh ảo nếu phù hợp). Thời gian điều trị kháng sinh CAP tiêu chuẩn ở người lớn là 5 ngày; riêng đối với trẻ em từ 3 tháng đến 11 tuổi bị CAP thể nhẹ không biến chứng, phác đồ kháng sinh hàng đầu (Amoxicillin) được khuyến cáo rút ngắn xuống còn 3 ngày để bảo vệ hệ vi sinh và hạn chế kháng thuốc. Với HAP, kháng sinh cũng được khuyến cáo xem xét dừng sau 5 ngày nếu lâm sàng ổn định. Đối với người lớn mắc CAP mức độ nặng nhập viện (CURB65 từ 3-5 điểm kèm đánh giá lâm sàng), khuyến cáo cân nhắc bổ sung Corticosteroid truyền tĩnh mạch (ưu tiên Hydrocortisone, hoặc Dexamethasone thay thế) trong 4-7 ngày. Xét nghiệm CRP hoặc procalcitonin (PCT) nên được đo vào ngày 3 hoặc 4 sau khi khởi trị kháng sinh nếu",
    "sourceUrl": "https://drive.google.com/file/d/1C-qHy2FTmXgFb46YqXO7geaIdJv4I4f3/view",
