    "drug": "Co-trimoxazole, Fluconazole, Liposomal amphotericin B, Flucytosine, Itraconazole, Paclitaxel, Pegylated liposomal doxorubicin, Ceftriaxone, Cefotaxime, Ampicillin, Amoxicillin, Prednisone, Dexamethasone",
