    "id": "2024-byt-dot-quy-nao",
    "title": "Bộ Y Tế 2024: Hướng Dẫn Quốc Gia Chẩn Đoán & Điều Trị Đột Quỵ Não (QĐ 3312/QĐ-BYT)",
    "titleEn": "Vietnam MOH 2024 National Guidelines on Diagnosis and Management of Stroke (Decision 3312/QD-BYT)",
    "sourceType": "vn-moh",
    "specialty": "neuro",
    "design": "guideline",
    "impact": "practice-changing",
    "year": 2024,
    "organization": "Bộ Y tế Việt Nam",
    "journal": "Bộ Y tế Việt Nam",
    "file": "2024-byt-dot-quy-nao.mdx",
    "conditionKey": "stroke",
    "icd10": [
      "I63",
      "I61",
      "I60",
      "G45",
      "I67.84",
      "F01"
    ],
    "intervention": "Hướng dẫn thực hành lâm sàng tiêu chuẩn quốc gia ban hành theo Quyết định 3312/QĐ-BYT của Bộ Y tế về đột quỵ não: Phân loại nguyên nhân nhồi máu não theo TOAST (xơ vữa mạch lớn, thuyên tắc tim, tắc mạch nhỏ, căn nguyên khác/chưa xác định); Phác đồ kháng tiểu cầu kép (DAPT) bằng Aspirin + Clopidogrel trong 21 - 90 ngày cho TIA nguy cơ cao (ABCD2 ≥ 4) và đột quỵ nhẹ (NIHSS ≤ 3), hoặc Aspirin + Ticagrelor 30 ngày cho nguy cơ rất cao (ABCD2 ≥ 5 hoặc NIHSS ≤ 5); Chiến lược kiểm soát huyết áp cấp: hạ < 185/110 mmHg trước khi dùng tiêu sợi huyết và duy trì < 180/105 mmHg trong 24h đầu, không hạ áp khi HA < 220/110 mmHg nếu không tiêu sợi huyết; Đích huyết áp trong chảy máu não: hạ sớm trong 2h đầu duy trì 130 - 150 mmHg trong 6h đầu và ổn định 7 ngày; Khảo sát hình ảnh học 4P (Parenchyma, Pipes, Perfusion, Penumbra) và thang điểm ASPECTS; Tiêu sợi huyết đường tĩnh mạch bằng Alteplase (0.9 mg/kg hoặc 0.6 mg/kg) hoặc Tenecteplase (0.25 mg/kg bolus duy nhất) trong cửa sổ 4.5h, mở rộng đến 9h hoặc đột quỵ thức giấc dựa vào bất tương xứng DWI-FLAIR / Perfusion; Can thiệp lấy huyết khối cơ học (LHKCH) bằng stent retriever hoặc hút áp lực âm trong cửa sổ 6h (ASPECTS ≥ 6) và mở rộng 6 - 24h theo DAWN / DEFUSE 3, đích tái thông mTICI 2b - 3; Phác đồ đảo ngược thuốc chống đông tức thời trong chảy máu não (PCC 25-50 U/kg + Vitamin K cho kháng vitamin K, Idarucizumab 5g cho Dabigatran, PCC cho kháng yếu tố Xa); Phân độ Fisher, Hunt-Hess và xử trí phình mạch não vỡ bằng can thiệp Coiling / Clipping sớm trong 24-72h kèm Nimodipine 60mg mỗi 4h đến ngày 21; Chẩn đoán dấu hiệu delta rỗng và chống đông sớm bằng LMWH/Heparin trong huyết khối tĩnh mạch não; Phân loại Spetzler-Martin trong AVM; Sa sút trí tuệ mạch máu (DSM-5, Donepezil, Memantine, Cerebrolysin, Citicoline); Dự phòng thứ phát hẹp động mạch cảnh (CEA/CAS trong 2 tuần đầu), xơ vữa nội sọ (DAPT), rung nhĩ (DOACs, quy tắc 1-3-6-12 ngày) và bít PFO qua da cho người 18-60 tuổi; Phục hồi chức năng đa chuyên ngành, vận động sớm tại giường trong 24-48h, bắt buộc sàng lọc nuốt sớm trước khi ăn uống, và tiêm Botulinum toxin cho co cứng cơ.",
    "primaryEndpoint": "Chuẩn hóa quy trình cấp cứu đột quỵ \"Code Stroke\", tối ưu hóa thời gian cửa - kim (Door-to-needle ≤ 60 phút), mở rộng tỷ lệ tái tưới máu an toàn bằng tiêu sợi huyết và can thiệp nội mạch, kiểm soát biến chứng xuất huyết não, giảm tỷ lệ tử vong và tàn phế, đồng thời nâng cao chất lượng phục hồi chức năng đa chuyên ngành sau đột quỵ tại Việt Nam.",
    "keyResults": "DAPT (Aspirin + Clopidogrel 21-90 ngày) giảm đột quỵ tái phát trong TIA nguy cơ cao và đột quỵ nhẹ | Tiêu sợi huyết tĩnh mạch Alteplase/Tenecteplase cửa sổ 4.5h (mở rộng đến 9h có mismatch) cứu sống đáng kể nhu mô não | Lấy huyết khối cơ học cửa sổ 6h (ASPECTS ≥ 6) và 6-24h (DAWN/DEFUSE 3) cải thiện ngoạn mục kết cục thần kinh | Hạ áp sớm trong 2h đầu (130 < HATT < 150) hạn chế khối máu tụ lan rộng trong xuất huyết não | Đảo ngược khẩn chống đông bằng PCC/Idarucizumab ngăn tử vong do xuất huyết não | Bít phình mạch não vỡ sớm trong 24-72h kèm Nimodipine phòng co thắt mạch | Chống đông sớm bằng Heparin/LMWH an toàn và giảm tử vong trong huyết khối tĩnh mạch não | Bắt buộc sàng lọc nuốt sớm phòng viêm phổi hít; tiêm Botulinum toxin giảm co cứng cơ.",
    "summary": "Hướng dẫn thực hành lâm sàng tiêu chuẩn quốc gia ban hành theo Quyết định 3312/QĐ-BYT ngày 05/11/2024 của Bộ Y tế: Cập nhật toàn diện 13 chương chuyên môn từ tiếp cận TIA/đột quỵ nhẹ, nhồi máu não cấp, chảy máu não, phình mạch não, huyết khối xoang tĩnh mạch, AVM, tiêu sợi huyết, lấy huyết khối cơ học đến phục hồi chức năng đa chuyên ngành.",
    "detailedConclusion": "Bác sĩ lâm sàng tiếp cận bệnh nhân đột quỵ não khẩn cấp: Chụp ngay CT/MRI sọ não không cản quang để phân biệt nhồi máu hay xuất huyết. Nếu nhồi máu não: Đánh giá cửa sổ 4.5h cho tiêu sợi huyết (Alteplase hoặc Tenecteplase) và tìm tắc mạch lớn để lấy huyết khối cơ học (cửa sổ 6-24h). Kiểm soát huyết áp chặt chẽ theo từng thể bệnh và cá thể hóa điều trị dự phòng thứ phát theo căn nguyên TOAST (kháng tiểu cầu kép, chống đông DOACs, bóc nội mạc mạch cảnh, bít PFO). Triển khai phục hồi chức năng đa chuyên ngành sớm và kiểm soát biến chứng rối loạn nuốt, co cứng cơ.",
    "drug": "Alteplase, Tenecteplase, Aspirin, Clopidogrel, Ticagrelor, Cilostazol, Dipyridamole, Dabigatran, Rivaroxaban, Apixaban, Edoxaban, Warfarin, Acenocoumarol, Nicardipin, Labetalol, Sodium nitroprusside, Mannitol, Natri clorua 3%, Citicoline, Cerebrolysin, Cholin alfoscerate, Piracetam, Atorvastatin, Rosuvastatin, Simvastatin, Pravastatin, Ezetimibe, Protamine sulfate, Idarucizumab, Desmopressin, Nimodipine, Fentanyl, Midazolam, Paracetamol, Diazepam, Phenytoin, Acetazolamide, Glucocorticoid",
    "population": "Người bệnh ở mọi lứa tuổi nghi ngờ hoặc xác định mắc đột quỵ não cấp tính (bao gồm nhồi máu não cấp, chảy máu não, chảy máu dưới nhện do vỡ phình mạch) hoặc cơn thiếu máu não thoáng qua (TIA).",
    "asianData": true,
