    "intervention": "Chẩn đoán hình ảnh ưu tiên chụp MRI sọ não chuỗi xung khuyếch tán DWI/ADC (Se 92%, Sp 91%); Trì hoãn kháng sinh ngắn ngày (< 24h) trước can thiệp ngoại khoa ở BN không nguy kịch giúp tăng tỷ lệ chẩn đoán vi sinh lên gấp 10 lần (OR = 10.5); Xét nghiệm sinh học phân tử 16S rDNA PCR và NGS khi cấy mủ âm tính; Can thiệp ngoại thần kinh sớm (chọc hút hoặc cắt bỏ) giúp giảm 50% nguy cơ tử vong (OR = 0.5, chất lượng bằng chứng mức Trung bình theo Corrigendum 2024); Phác đồ kháng sinh kinh nghiệm theo 3 nhóm nguy cơ (Cộng đồng: Ceph III + Metronidazole; Suy giảm miễn dịch: Ceph III + Metro + Voriconazole + TMP-SMX; Sau mổ: Meropenem + Vancomycin/Linezolid); Thời gian điều trị 6-8 tuần (chọc hút/bảo tồn) vs 4 tuần (cắt bỏ triệt để); Dexamethasone bổ trợ cho phù não nặng và khuyến cáo chống lại dùng thuốc chống động kinh dự phòng thường quy.",
