    "intervention": "Chụp CT bụng có cản quang đường tĩnh mạch (IV contrast) là lựa chọn hình ảnh ban đầu ưu tiên cho người lớn và vị thành niên; Siêu âm ổ bụng là phương tiện đầu tay cho trẻ em (tránh phơi nhiễm bức xạ ion hóa), tiếp nối bằng CT hoặc MRI nếu siêu âm âm tính/không rõ ràng; Cân nhắc Siêu âm hoặc MRI cho phụ nữ mang thai (không dùng bức xạ); Nguyên tắc vàng thời gian sau phẫu thuật: áp xe mất ít nhất 5 ngày mới tạo vỏ bao xơ (tránh chụp CT ngày 1-4 sau mổ gây dương tính giả dịch tụ sinh lý); Đánh giá nguy cơ sai lệch QUADAS-2 và phân tích lý do hạ bậc chất lượng chứng cứ GRADE (Rất thấp do thiếu nghiên cứu RCT so sánh đối đầu trực diện).",
    "primaryEndpoint": "Chuẩn hóa quy trình lựa chọn phương tiện chẩn đoán hình ảnh tối ưu, xác định sớm ổ áp xe ổ bụng để kiểm soát nguồn nhiễm ngoại khoa kịp thời và tránh các can thiệp không cần thiết do chụp quá sớm sau mổ.",
    "keyResults": "CT có cản quang IV ưu tiên cho người lớn | Siêu âm ưu tiên cho trẻ em (CT/MRI tiếp nối khi không rõ ràng) | Cân nhắc US/MRI cho thai phụ | Áp xe cần ≥ 5 ngày sau mổ để hoàn thiện vỏ bao xơ | Toàn bộ khuyến cáo đạt mức bằng chứng Rất thấp theo GRADE do thiếu nghiên cứu đối đầu.",
    "summary": "Cập nhật hướng dẫn thực hành lâm sàng năm 2024 của IDSA (Bonomo et al., CID): Tích hợp thuật toán chẩn đoán hình ảnh phân tầng cho 3 đối tượng bệnh nhân, nguyên tắc thời điểm sau phẫu thuật (≥ 5 ngày), đánh giá nguy cơ sai lệch QUADAS-2 và giải thích lý do xếp hạng GRADE mức Rất thấp.",
    "detailedConclusion": "Bác sĩ lâm sàng chỉ định CT bụng có cản quang IV cho người lớn và vị thành niên. Đối với trẻ em, khởi đầu bằng Siêu âm và chỉ chuyển sang CT/MRI khi siêu âm không thể kết luận. Lưu ý không chụp CT quá sớm vào ngày 1 - 4 sau mổ để tránh chẩn đoán nhầm dịch tụ sinh lý với áp xe thực sự.",
    "drug": "Thuốc cản quang tĩnh mạch (IV contrast)",
    "population": "Người lớn, trẻ em và phụ nữ mang thai nghi ngờ mắc áp-xe ổ bụng cấp tính hoặc có biến chứng áp-xe tiến triển sau phẫu thuật.",
