    "title": "Tác động của việc thả muỗi Aedes aegypti mang vi khuẩn Wolbachia chủng wMel đối với số ca bệnh sốt xuất huyết báo cáo và phun hóa chất diệt muỗi tại thành phố Yogyakarta]",
