    "keyResults": "PCR là tiêu chuẩn vàng chẩn đoán căn nguyên | Phát ban ly tâm cùng lứa tuổi và sưng hạch phân biệt tin cậy với Thủy đậu, Đậu mùa, Tay chân miệng | Chỉ định thuốc kháng vi rút (Tecovirimat, Brincidofovir, Cidofovir) cho thể nặng/nguy cơ cao | Cidofovir bắt buộc phối hợp Probenecid và bù dịch 1L bảo vệ thận, chống chỉ định thai kỳ | Tiêu chuẩn kết thúc cách ly: ≥ 14 ngày VÀ không có tổn thương mới trong 48h kèm bong vảy khô hoàn toàn.",
