    "primaryEndpoint": "Bảo tồn và phục hồi khối cơ, cải thiện lực co bóp cơ (suy yếu), giảm tỷ lệ nhập viện ngoài ý muốn, giảm đợt mất bù xơ gan và tử vong danh sách chờ ghép",
    "keyResults": "LES cải thiện tổng protein cơ thể và khối cơ; Đạm 1.2-1.5 g/kg an toàn trong HE; LFI ≥ 4.4 xác định suy yếu nặng; Đạt ≥ 22 kcal/kg/ngày ở viêm gan rượu giảm 67% tử vong; Kháng sinh/Testosterone và tập F.I.T.T cải thiện rõ rệt thể trạng.",
    "summary": "Hướng dẫn thực hành lâm sàng chính thức của AASLD 2021 về Dinh dưỡng, Suy yếu và Teo cơ trong xơ gan: Sinh lý bệnh 5 động lực, công cụ LFI/CT-SMI, đơn thuốc dinh dưỡng cá thể hóa, vai trò bữa phụ đêm muộn (LES), dinh dưỡng nội trú/ICU, phác đồ tập luyện F.I.T.T, bù vi chất và testosterone.",
