    "primaryEndpoint": "Chuẩn hóa quy trình phát hiện sớm nhiễm nấm xâm lấn, phối hợp biomarker và hình ảnh học HRCT ngực, tối ưu hóa phác đồ kháng nấm đặc hiệu, quản lý TDM và hạ thấp tỷ lệ tử vong do nhiễm nấm huyết và nấm phổi hoại tử.",
    "keyResults": "Echinocandins là lựa chọn số 1 cho Candida máu và mô sâu | Bắt buộc rút CVC trong 24–48h và soi đáy mắt tuần đầu loại trừ viêm nội nhãn | C. tropicalis tại VN kháng Fluconazole lên tới 67.1% | Voriconazole là lựa chọn hàng đầu cho IPA với TDM mục tiêu 1.5–4.5 µg/mL | GM dịch BAL có giá trị vượt trội so với huyết thanh ở bệnh nhân ICU | Không dùng Corticosteroid hay Mannitol hạ áp lực nội sọ trong Cryptococcus | Bắt buộc Corticosteroid sớm trong 72h đầu cho PJP có PaO2 < 70 mmHg.",
    "summary": "Hướng dẫn chuyên môn toàn diện ban hành theo Quyết định 3429/QĐ-BYT năm 2021 của Bộ Y tế (PGS.TS. Lương Ngọc Khuê chủ biên, GS.TS. Nguyễn Gia Bình đồng chủ biên cùng chuyên gia BV Bạch Mai, Chợ Rẫy, Bệnh Nhiệt đới TW, ĐH Dược Hà Nội): Tích hợp đầy đủ lưu đồ Candida và IPA, tiêu chuẩn AspICU và Bulpa, bảng liều thuốc chi tiết, hướng dẫn TDM và xử trí độc tính kháng nấm.",
    "detailedConclusion": "Bác sĩ lâm sàng chủ động phân tầng nguy cơ IFD, kết hợp biomarker GM/BDG và HRCT ngực sớm. Ưu tiên khởi đầu Echinocandins cho Candida máu, rút ngay CVC và soi đáy mắt tuần đầu. Với Aspergillus phổi, chỉ định Voriconazole kết hợp đo TDM thường quy. Bệnh nhân PJP suy hô hấp bắt buộc bổ sung Prednisone sớm trong 72h đầu; và viêm màng não Cryptococcus phải kiểm soát áp lực nội sọ bằng chọc tháo dịch não tủy hằng ngày.",
    "drug": "Amphotericin B deoxycholat, Amphotericin B phức hợp lipid, Amphotericin B liposom, Caspofungin, Micafungin, Anidulafungin, Fluconazol, Itraconazol, Voriconazol, Posaconazol, Isavuconazol, Flucytosin, Trimethoprim, Sulfamethoxazole, Clindamycin, Primaquine, Pentamidine, Atovaquone, Prednisone, Methylprednisolone, Hydrocortisone, Heparin, Pethidin",
