    "keyResults": "Tỷ lệ tử vong gộp chung 24% | > 90% tử vong tập trung trong 3 tháng đầu (23% tại mốc 3 tháng) | Tỷ lệ tử vong ở người đồng nhiễm HIV lên tới 57% (so với 16% không nhiễm HIV, P < 0.001) | Tỷ lệ tàn tật thần kinh ở người sống sót đạt 32% | Không có sự cải thiện sống còn trong suốt hơn 20 năm qua.",
    "summary": "Tổng quan hệ thống và phân tích gộp lớn nhất của IDSA/OFID về kết cục điều trị lao màng não ở 5.752 người lớn từ 39 nghiên cứu: Xác định tỷ lệ tử vong 24%, tập trung > 90% trong 3 tháng đầu, nguy cơ tử vong tăng gấp 3.5 lần ở nhóm HIV (57% vs 16%), 32% người sống sót bị tàn tật thần kinh vĩnh viễn, và đồng thuận quốc tế chuẩn hóa đo lường mRS tại mốc 12 tháng.",
