    "intervention": "Chẩn đoán không xâm lấn (FIB-4/M2BPGi/Elastography), Dinh dưỡng LES + BCAAs, Tolvaptan sớm (3.75-7.5 mg/ngày), CART vs LVP, BRTO cho giãn TM phình vị cô lập (bảo hiểm Nhật 2018), Rifaximin + Kẽm 6 tháng + L-Carnitine cho HE, NAs bắt buộc mọi xơ gan HBV, Sofosbuvir/Velpatasvir cho mất bù HCV, Lusutrombopag giảm tiểu cầu, Nalfurafine ngứa gan mật kháng trị",
    "primaryEndpoint": "Cải thiện sống còn, giảm tỷ lệ biến chứng mất bù (cổ trướng, HE, xuất huyết vỡ giãn, HRS-AKI), giảm tỷ lệ HCC, cải thiện chất lượng cuộc sống và ngăn ngừa teo cơ",
    "keyResults": "Tolvaptan sớm (★ đặc điểm Nhật Bản): Tiêu chí đáp ứng sau 1 tuần: giảm > 1.5 kg. BRTO vượt trội NBCA trong dự phòng tái xuất huyết IGV (bảo hiểm 2018). Rifaximin an toàn 24 tháng: Giảm PSE index và NCT-A. Kẽm 6 tháng: Cải thiện HRQOL và giảm amoniac. HCC sau SVR: 1.8-2.5%/năm dù sạch virus → Tầm soát suốt đời bắt buộc. Entecavir/TDF: 66-68.4% đạt Child-Pugh A sau 12 tháng.",
    "summary": "Hướng dẫn JSGE-JSH 2020 chuẩn hóa 4 thuật toán lâm sàng (Fig 1-4) dưới dạng SVG tiếng Việt: (1) Thuật toán chẩn đoán xơ gan F4 không xâm lấn; (2) Thuật toán liệu pháp dinh dưỡng phân tầng PEM/BMI/Sarcopenia với vòng phản hồi BCAA 1-2 tháng; (3) Thuật toán chẩn đoán phân biệt dịch cổ trướng bằng SAAG ≥/< 1.1 g/dL; (4) Thuật toán điều trị bậc thang cổ trướng từ Spironolactone → Tolvaptan → Canrenoate IV → LVP/CART → TIPS/PVS → Ghép gan.",
    "detailedConclusion": "Điều trị cổ trướng: Khởi trị Tolvaptan sớm khi kháng/không dung nạp lợi tiểu, không tăng liều Furosemide quá mức gây suy thận. BRTO được ưu tiên hơn tiêm keo NBCA cho giãn TM phình vị cô lập do vượt trội trong cả ngừa xuất huyết và cải thiện HE. Cảnh báo PPI dài hạn (>1 năm) làm tăng SBP, HE và CKD. Tuyệt đối tầm soát HCC suốt đời sau SVR bằng siêu âm + AFP do tỷ lệ HCC mới vẫn 1.8-2.5%/năm. ACEi/ARBs chống chỉ định tuyệt đối ở xơ gan mất bù có cổ trướng.",
    "drug": "Spironolactone, Furosemide, Tolvaptan, Potassium Canrenoate, Albumin, Noradrenaline, Terlipressin, Carvedilol, Propranolol, Rifaximin, Lactulose, BCAAs, Zinc, L-Carnitine, Lusutrombopag, Nalfurafine, Entecavir, Tenofovir TDF, Sofosbuvir/Velpatasvir",
